        scrollW: root.scrollWidth, clientW: root.clientWidth,
        accent: cs(root).getPropertyValue('--ult-color-accent').trim(),
        scheme: cs(root).colorScheme, bg: cs(document.body).backgroundColor || cs(root).backgroundColor,
